SELECT
    ni.*,nf.head_user
FROM
    nxp_inspection ni
LEFT JOIN nxp_facility nf ON ni.facility_id = nf.id
LEFT JOIN nxp_machine_process nmp ON nf.process = nmp.id

    and ni.id = #{id}
    and ni.status = #{status}
    and nf.id = #{facility_id}
    and ni.question_type = #{question_type}
    and nmp.id = #{process_id}
    and ni.is_top = #{is_top}
    and repair_time between #{params.repair_start_time} and #{params.repair_end_time}

order by ni.id desc

